// Port of lib/utilities/us_zip_codes.rb. The zip -> state table is config/zip_code_database.csv plus
// KNOWN_ZIP_CODES (config/initializers/united_states_zip_codes.rb), generated by scripts/generate-us-zip-states.ts.
import ZIP_STATES from "./us-zip-states.generated.json" with { type: "json" };

// Known zip codes that don't show up in the US Zip Codes database.
const KNOWN_ZIP_CODES: Readonly<Record<string, string>> = { "85144": "AZ" };

const ZIP_CODE_TO_STATE = new Map<string, string>();
for (const [state, zips] of Object.entries(ZIP_STATES)) for (const zip of zips.split(" ")) ZIP_CODE_TO_STATE.set(zip, state);
for (const [zip, state] of Object.entries(KNOWN_ZIP_CODES)) ZIP_CODE_TO_STATE.set(zip, state);

const ASCII_WHITESPACE = /^[\t\n\v\f\r \0]+|[\t\n\v\f\r \0]+$/gu;
const ALL_DIGITS = /^\d*$/u;

// 5-digit zip, zip+4 with no separator, or zip+4 with a single space or hyphen. Only the first 5 digits decide the state.
export function identifyStateCode(zipCode: string | number | null | undefined): string | null {
  if (zipCode == null) return null;
  const zipString = String(zipCode).replace(ASCII_WHITESPACE, "");
  if (zipString === "") return null;

  const validStructure =
    (zipString.length === 5 && ALL_DIGITS.test(zipString)) ||
    (zipString.length === 9 && ALL_DIGITS.test(zipString)) ||
    (zipString.length === 10 &&
      (zipString[5] === " " || zipString[5] === "-") &&
      // Ruby: zip_string.split(separator).all? { |part| part !~ /\D/ }
      zipString.split(zipString[5]!).every((part) => ALL_DIGITS.test(part)));
  if (!validStructure) return null;

  return ZIP_CODE_TO_STATE.get(zipString.slice(0, 5)) ?? null;
}
